-- ---------------------------------------------------------------------------------------------
-- 1. Tables.
-- ---------------------------------------------------------------------------------------------
create table if not exists private.titan_club_events (
  id uuid primary key default gen_random_uuid(),
  club_id uuid not null references private.titan_clubs(id) on delete cascade,
  title text not null check (char_length(title) between 3 and 60),
  area text not null check (char_length(area) between 2 and 60),
  place text check (place is null or char_length(place) between 2 and 200),
  fallback text check (fallback is null or char_length(fallback) between 3 and 200),
  duration_min integer not null check (duration_min between 15 and 480),
  capacity integer check (capacity is null or capacity between 2 and 100),
  recurrence text not null check (recurrence in ('once', 'weekly')),
  occurrences integer not null check (occurrences between 1 and 12),
  code text not null unique check (code ~ '^[A-Z2-9]{8}$'),
  status text not null default 'active' check (status in ('active', 'cancelled')),
  cancelled_at timestamptz,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  check ((recurrence = 'once') = (occurrences = 1))
);
create index if not exists titan_club_events_club_idx on private.titan_club_events (club_id, created_at desc);

create table if not exists private.titan_club_event_slots (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references private.titan_club_events(id) on delete cascade,
  n integer not null check (n between 1 and 12),
  planned_at timestamptz not null,
  starts_at timestamptz not null,
  status text not null default 'scheduled' check (status in ('scheduled', 'cancelled')),
  by_series boolean not null default false,
  fallback_on boolean not null default false,
  changed_at timestamptz,
  unique (event_id, n)
);
create index if not exists titan_club_event_slots_start_idx on private.titan_club_event_slots (starts_at);

create table if not exists private.titan_club_event_answers (
  slot_id uuid not null references private.titan_club_event_slots(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  answer text check (answer in ('yes', 'maybe', 'no', 'waitlist')),   -- null: a presence declared without an answer before
  answered_at timestamptz not null default now(),       -- when this answer was first given (the order of the waiting list)
  confirmed_at timestamptz not null default now(),      -- when it was last given or repeated (a change after it is « to confirm »)
  promoted_at timestamptz,
  reminder boolean not null default false,
  attended boolean,
  attended_at timestamptz,
  log_id uuid references public.training_logs(id) on delete set null,
  linked_at timestamptz,
  primary key (slot_id, user_id),
  check (log_id is null or attended is true)
);
create index if not exists titan_club_event_answers_user_idx on private.titan_club_event_answers (user_id);
-- A session of the journal is linked to one meeting at most.
create unique index if not exists titan_club_event_answers_log_uniq on private.titan_club_event_answers (log_id) where log_id is not null;

create table if not exists private.titan_club_event_changes (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references private.titan_club_events(id) on delete cascade,
  slot_id uuid references private.titan_club_event_slots(id) on delete cascade,
  kind text not null check (kind in ('created', 'moved', 'fallback_on', 'fallback_off', 'cancelled', 'restored', 'series_cancelled', 'series_resumed', 'code_renewed')),
  from_at timestamptz,
  to_at timestamptz,
  by_user uuid references auth.users(id) on delete set null,
  at timestamptz not null default clock_timestamp()
);
create index if not exists titan_club_event_changes_event_idx on private.titan_club_event_changes (event_id, at);

alter table private.titan_club_events enable row level security;
alter table private.titan_club_event_slots enable row level security;
alter table private.titan_club_event_answers enable row level security;
alter table private.titan_club_event_changes enable row level security;
revoke all on private.titan_club_events, private.titan_club_event_slots, private.titan_club_event_answers, private.titan_club_event_changes
  from public, anon, authenticated;

