create or replace function private.titan_club_agenda_code()
returns text
language plpgsql
volatile
set search_path = ''
as $function$
declare v_chars constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; v_code text; i integer;
begin
  loop
    v_code := '';
    for i in 1..8 loop v_code := v_code || substr(v_chars, 1 + floor(random() * length(v_chars))::integer, 1); end loop;
    exit when not exists (select 1 from private.titan_club_events where code = v_code);
  end loop;
  return v_code;
end;
$function$;
revoke all on function private.titan_club_agenda_code() from public, anon, authenticated;

