$$;
revoke all on function private.titan_club_agenda_change(uuid, uuid, text, timestamptz, timestamptz, uuid) from public, anon, authenticated;

-- A place freed goes to the first one waiting, in order of answer, until the capacity is reached. The caller holds the occurrence lock.
create or replace function private.titan_club_agenda_fill(p_slot uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $function$
declare v_cap integer; v_yes integer; v_user uuid; v_done integer := 0;
begin
  select e.capacity into v_cap from private.titan_club_event_slots s join private.titan_club_events e on e.id = s.event_id where s.id = p_slot;
  if v_cap is null then
    -- No capacity (or none any more): nobody waits.
    update private.titan_club_event_answers set answer = 'yes', promoted_at = clock_timestamp() where slot_id = p_slot and answer = 'waitlist';
    get diagnostics v_done = row_count;
    return v_done;
  end if;
  loop
    select count(*) into v_yes from private.titan_club_event_answers where slot_id = p_slot and answer = 'yes';
    exit when v_yes >= v_cap;
    select a.user_id into v_user from private.titan_club_event_answers a where a.slot_id = p_slot and a.answer = 'waitlist'
     order by a.answered_at, a.user_id limit 1;
    exit when v_user is null;
    update private.titan_club_event_answers set answer = 'yes', promoted_at = clock_timestamp() where slot_id = p_slot and user_id = v_user;
    v_done := v_done + 1;
    v_user := null;
  end loop;
  return v_done;
end;
$function$;
revoke all on function private.titan_club_agenda_fill(uuid) from public, anon, authenticated;

-- A session that may be linked: one's own CONFIRMED session (valid, not suspicious, stamped by the server, no held or cancelled reward)
-- of the Paris day on which the occurrence started.
create or replace function private.titan_club_agenda_log_ok(p_slot uuid, p_user uuid, p_log uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from private.titan_club_event_slots s
     cross join lateral (select ((s.starts_at at time zone 'Europe/Paris')::date)::timestamp at time zone 'Europe/Paris' as d0) d
     cross join lateral private.titan_confirmed_sessions(p_user, d.d0, d.d0 + interval '1 day', '-infinity'::timestamptz) x
     where s.id = p_slot and x.log_id = p_log);
$$;
revoke all on function private.titan_club_agenda_log_ok(uuid, uuid, uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 3. What a member of the club reads of one occurrence (p_role = 'admin' | 'member').
-- ---------------------------------------------------------------------------------------------
create or replace function private.titan_club_agenda_slot(p_slot uuid, p_viewer uuid, p_role text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  s private.titan_club_event_slots%rowtype;
  e private.titan_club_events%rowtype;
  a private.titan_club_event_answers%rowtype;
  v_end timestamptz; v_phase text; v_flag boolean := private.titan_flag_on('screens.club_agenda');
  v_can jsonb := '[]'::jsonb; v_suspended boolean; v_counts jsonb; v_yes integer; v_place boolean; v_pos integer;
  v_report jsonb; v_linked integer; v_me jsonb; v_candidates jsonb; v_d0 timestamptz;
begin
  select * into s from private.titan_club_event_slots where id = p_slot;
  if s.id is null then return null; end if;
  select * into e from private.titan_club_events where id = s.event_id;
  select * into a from private.titan_club_event_answers where slot_id = s.id and user_id = p_viewer;
  v_end := s.starts_at + make_interval(mins => e.duration_min);
  v_phase := case when s.status = 'cancelled' then 'cancelled' when now() < s.starts_at then 'upcoming' when now() < v_end then 'running' else 'ended' end;
  v_suspended := exists (select 1 from public.profiles p where p.id = p_viewer and coalesce(p.is_suspended, false));
  select jsonb_build_object('yes', count(*) filter (where x.answer = 'yes'), 'maybe', count(*) filter (where x.answer = 'maybe'),
           'waitlist', count(*) filter (where x.answer = 'waitlist'), 'no', count(*) filter (where x.answer = 'no')),
         count(*) filter (where x.answer = 'yes')
    into v_counts, v_yes from private.titan_club_event_answers x where x.slot_id = s.id;
  if a.answer = 'waitlist' then
    select count(*) + 1 into v_pos from private.titan_club_event_answers x
     where x.slot_id = s.id and x.answer = 'waitlist' and (x.answered_at, x.user_id) < (a.answered_at, a.user_id);
  end if;
  -- The precise place: administrators, and members who come, hesitate or wait, until the end; never once cancelled.
  v_place := e.place is not null and v_phase in ('upcoming', 'running') and (p_role = 'admin' or a.answer in ('yes', 'maybe', 'waitlist'));

  if v_phase = 'upcoming' then
    if not v_suspended and v_flag then
      if a.answer is distinct from 'yes' and a.answer is distinct from 'waitlist' then v_can := v_can || '["yes"]'::jsonb; end if;
      if a.answer is distinct from 'maybe' then v_can := v_can || '["maybe"]'::jsonb; end if;
    end if;
    if a.answer is distinct from 'no' then v_can := v_can || '["no"]'::jsonb; end if;
    if a.answer in ('yes', 'maybe', 'waitlist') and (v_flag or a.reminder) then v_can := v_can || '["remind"]'::jsonb; end if;
    if p_role = 'admin' then
      if v_flag then v_can := v_can || '["move"]'::jsonb; end if;
      if e.fallback is not null and (v_flag or s.fallback_on) then v_can := v_can || '["fallback"]'::jsonb; end if;
      v_can := v_can || '["cancel"]'::jsonb;
    end if;
  elsif v_phase = 'cancelled' and p_role = 'admin' and now() < s.starts_at and v_flag and e.status = 'active' then
    v_can := v_can || '["restore"]'::jsonb;
  elsif v_phase in ('running', 'ended') and now() < v_end + interval '7 days' then
    v_can := v_can || '["attend"]'::jsonb;
    if a.attended is true then v_can := v_can || (case when a.log_id is null then '["link"]' else '["unlink"]' end)::jsonb; end if;
  end if;

  if v_phase in ('running', 'ended') then
    select count(*) into v_linked from private.titan_club_event_answers x where x.slot_id = s.id and x.log_id is not null;
    v_report := jsonb_build_object('present', (select count(*) from private.titan_club_event_answers x where x.slot_id = s.id and x.attended is true),
      'linked', v_linked, 'threshold', 3, 'visible', v_linked >= 3);
    if v_linked >= 3 then
      v_report := v_report || (select jsonb_build_object(
          'minutes', round(sum(least(90, coalesce(public.titan_numeric_from_json(l.details -> 'effort', 'effort_minutes'), 0))))::integer,
          'km', round(sum(case when l.unit = 'km' then least(l.val, 300) else 0 end), 1),
          'sports', count(distinct l.sport))
        from private.titan_club_event_answers x join public.training_logs l on l.id = x.log_id
       where x.slot_id = s.id and x.log_id is not null);
    end if;
    if a.attended is true and a.log_id is null and now() < v_end + interval '7 days' then
      v_d0 := ((s.starts_at at time zone 'Europe/Paris')::date)::timestamp at time zone 'Europe/Paris';
      select coalesce(jsonb_agg(jsonb_build_object('id', x.log_id, 'sport', x.sport, 'minutes', round(least(90, x.effort_minutes))::integer,
               'unit', x.unit, 'val', x.val) order by x.log_id), '[]'::jsonb)
        into v_candidates
        from private.titan_confirmed_sessions(p_viewer, v_d0, v_d0 + interval '1 day', '-infinity'::timestamptz) x
       where not exists (select 1 from private.titan_club_event_answers y where y.log_id = x.log_id);
    end if;
  end if;

  if a.user_id is not null then
    v_me := jsonb_build_object('answer', a.answer, 'answeredAt', a.confirmed_at, 'reminder', a.reminder, 'position', v_pos,
      'promoted', a.promoted_at is not null and a.answer = 'yes', 'toConfirm', a.answer in ('yes', 'maybe', 'waitlist') and s.changed_at is not null and s.changed_at > a.confirmed_at,
      'attended', a.attended,
      'linked', case when a.log_id is not null then (select jsonb_build_object('id', l.id, 'sport', l.sport,
                  'minutes', round(least(90, coalesce(public.titan_numeric_from_json(l.details -> 'effort', 'effort_minutes'), 0)))::integer)
                  from public.training_logs l where l.id = a.log_id) end,
      'candidates', v_candidates);
  end if;

  return jsonb_build_object('id', s.id, 'event', e.id, 'n', s.n, 'occurrences', e.occurrences, 'recurrence', e.recurrence,
    'title', e.title, 'area', e.area, 'durationMin', e.duration_min, 'startsAt', s.starts_at, 'endsAt', v_end, 'plannedAt', s.planned_at,
    'moved', s.starts_at <> s.planned_at, 'phase', v_phase, 'series', e.status, 'fallback', e.fallback, 'fallbackOn', s.fallback_on,
    'capacity', e.capacity, 'full', e.capacity is not null and v_yes >= e.capacity, 'counts', v_counts,
    'hasPlace', e.place is not null, 'place', case when v_place then e.place end,
    'code', case when p_role = 'admin' then e.code end,
    'me', v_me, 'can', v_can, 'report', v_report, 'suspended', v_suspended,
    'history', coalesce((select jsonb_agg(jsonb_build_object('kind', c.kind, 'n', (select y.n from private.titan_club_event_slots y where y.id = c.slot_id),
                  'from', c.from_at, 'to', c.to_at, 'at', c.at) order by c.at, c.id)
                from private.titan_club_event_changes c
               where c.event_id = e.id and (c.slot_id = s.id or c.slot_id is null) and c.kind <> 'code_renewed'), '[]'::jsonb),
    -- Only administrators read who answered what (the public username, as on the club roster they moderate).
    'roster', case when p_role = 'admin' then coalesce((select jsonb_agg(jsonb_build_object('name', coalesce(nullif(p.username, ''), 'Athlète'),
                  'answer', x.answer, 'attended', x.attended) order by array_position(array['yes', 'waitlist', 'maybe', 'no'], x.answer), x.answered_at)
                from private.titan_club_event_answers x join public.profiles p on p.id = x.user_id
                where x.slot_id = s.id), '[]'::jsonb) end);
end;
$function$;
revoke all on function private.titan_club_agenda_slot(uuid, uuid, text) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 4. The API: read, act, open an invitation link.
-- ---------------------------------------------------------------------------------------------
create or replace function public.titan_club_agenda_v1(p_club uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
set statement_timeout = '8s'
as $function$
declare v_uid uuid := auth.uid(); v_role text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  select m.role into v_role from private.titan_club_members m join private.titan_clubs c on c.id = m.club_id
   where m.club_id = p_club and m.user_id = v_uid and c.archived_at is null;
  if v_role is null then raise exception 'CLUB_NOT_FOUND' using errcode = 'P0002'; end if;
  return jsonb_build_object('club', p_club, 'role', case when v_role = 'admin' then 'organizer' else 'member' end,
    'canCreate', v_role = 'admin' and private.titan_flag_on('screens.club_agenda'),
    -- To come (cancelled ones included, so that a cancellation stays readable), the next 60 days, 20 at most.
    'upcoming', coalesce((select jsonb_agg(private.titan_club_agenda_slot(x.id, v_uid, v_role) order by x.starts_at, x.id) from (
        select s.id, s.starts_at from private.titan_club_event_slots s join private.titan_club_events e on e.id = s.event_id
         where e.club_id = p_club and s.starts_at + make_interval(mins => e.duration_min) > now() and s.starts_at < now() + interval '60 days'
         order by s.starts_at, s.id limit 20) x), '[]'::jsonb),
    -- Finished in the last 30 days and held (not cancelled), 10 at most.
    'past', coalesce((select jsonb_agg(private.titan_club_agenda_slot(x.id, v_uid, v_role) order by x.starts_at desc, x.id) from (
        select s.id, s.starts_at from private.titan_club_event_slots s join private.titan_club_events e on e.id = s.event_id
         where e.club_id = p_club and s.status = 'scheduled' and s.starts_at + make_interval(mins => e.duration_min) <= now()
           and s.starts_at > now() - interval '30 days'
         order by s.starts_at desc, s.id limit 10) x), '[]'::jsonb));
end;
$function$;

create or replace function public.titan_club_agenda_act_v1(p_club uuid, p_action text, p_slot uuid default null, p_event uuid default null,
  p_answer text default null, p_on boolean default null, p_starts_at timestamptz default null, p_log uuid default null, p_form jsonb default null)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $function$
declare
  v_uid uuid := auth.uid();
  v_role text;
  v_flag boolean := private.titan_flag_on('screens.club_agenda');
  e private.titan_club_events%rowtype;
  s private.titan_club_event_slots%rowtype;
  a private.titan_club_event_answers%rowtype;
  v_title text; v_area text; v_place text; v_fallback text; v_duration integer; v_capacity integer; v_rec text; v_count integer;
  v_first timestamptz; v_id uuid; k integer; v_yes integer; v_end timestamptz; v_answer text; v_cnt integer;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  if p_action is null or p_action not in ('create', 'answer', 'remind', 'attend', 'link', 'unlink', 'move', 'fallback', 'cancel', 'restore',
       'cancel_series', 'resume_series', 'new_code') then raise exception 'AGENDA_INVALID' using errcode = '22023'; end if;
  if not v_flag and (p_action in ('create', 'move', 'restore', 'resume_series', 'new_code')
       or (p_action = 'answer' and p_answer in ('yes', 'maybe')) or (p_action = 'remind' and p_on is true)
       or (p_action = 'fallback' and coalesce(p_on, true))) then
    raise exception 'FEATURE_DISABLED' using errcode = '42501';
  end if;
  select cm.role into v_role from private.titan_club_members cm join private.titan_clubs c on c.id = cm.club_id
   where cm.club_id = p_club and cm.user_id = v_uid and c.archived_at is null;
  if v_role is null then raise exception 'CLUB_NOT_FOUND' using errcode = 'P0002'; end if;
  if p_action in ('create', 'move', 'fallback', 'cancel', 'restore', 'cancel_series', 'resume_series', 'new_code') and v_role <> 'admin' then
    raise exception 'CLUB_ADMIN_REQUIRED' using errcode = '42501';
  end if;
  if (p_action = 'create' or (p_action = 'answer' and p_answer in ('yes', 'maybe')))
     and exists (select 1 from public.profiles p where p.id = v_uid and coalesce(p.is_suspended, false)) then
    raise exception 'ACCOUNT_SUSPENDED' using errcode = '42501';
  end if;
  -- Every action on a club's agenda goes through the club row lock, then the occurrence row lock.
  perform 1 from private.titan_clubs where id = p_club for update;

  if p_action = 'create' then
    if not private.titan_can_vote(v_uid) then raise exception 'NOT_ELIGIBLE' using errcode = '42501'; end if;
    perform private.titan_rate_limit(v_uid, 'club_agenda_create', 10);
    v_title := private.titan_club_text(p_form ->> 'title', 60);
    v_area := private.titan_club_text(p_form ->> 'area', 60);
    v_place := private.titan_club_text(p_form ->> 'place', 200);
    v_fallback := private.titan_club_text(p_form ->> 'fallback', 200);
    v_rec := coalesce(p_form ->> 'recurrence', 'once');
    begin
      v_duration := (p_form ->> 'durationMin')::integer;
      v_capacity := nullif(p_form ->> 'capacity', '')::integer;
      v_count := coalesce((p_form ->> 'occurrences')::integer, 1);
      v_first := (p_form ->> 'startsAt')::timestamptz;
    exception when others then raise exception 'AGENDA_INVALID' using errcode = '22023';
    end;
    if v_title is null or char_length(v_title) not between 3 and 60 or v_area is null or char_length(v_area) not between 2 and 60
       or (v_place is not null and char_length(v_place) not between 2 and 200) or (v_fallback is not null and char_length(v_fallback) not between 3 and 200)
       or v_duration is null or v_duration not between 15 and 480 or (v_capacity is not null and v_capacity not between 2 and 100)
       or v_rec not in ('once', 'weekly') or (v_rec = 'once' and v_count <> 1) or (v_rec = 'weekly' and v_count not between 2 and 12)
       or v_first is null or v_first < now() + interval '30 minutes' or v_first > now() + interval '60 days' then
      raise exception 'AGENDA_INVALID' using errcode = '22023';
    end if;
    -- At most 10 series with an occurrence to come per club.
    if (select count(*) from private.titan_club_events x where x.club_id = p_club and x.status = 'active'
          and exists (select 1 from private.titan_club_event_slots y where y.event_id = x.id and y.starts_at > now())) >= 10 then
      raise exception 'AGENDA_LIMIT' using errcode = '22023';
    end if;
    insert into private.titan_club_events (club_id, title, area, place, fallback, duration_min, capacity, recurrence, occurrences, code, created_by)
    values (p_club, v_title, v_area, v_place, v_fallback, v_duration, v_capacity, v_rec, v_count, private.titan_club_agenda_code(), v_uid)
    returning id into v_id;
    -- Every occurrence at the same Paris wall-clock time: a change of hour in between keeps 18:30 at 18:30.
    for k in 1..v_count loop
      insert into private.titan_club_event_slots (event_id, n, planned_at, starts_at)
      values (v_id, k, ((v_first at time zone 'Europe/Paris') + make_interval(days => 7 * (k - 1))) at time zone 'Europe/Paris',
                       ((v_first at time zone 'Europe/Paris') + make_interval(days => 7 * (k - 1))) at time zone 'Europe/Paris');
    end loop;
    perform private.titan_club_agenda_change(v_id, null, 'created', null, v_first, v_uid);
    return public.titan_club_agenda_v1(p_club) || jsonb_build_object('created', v_id);
  end if;

  -- Series-wide actions.
  if p_action in ('cancel_series', 'resume_series', 'new_code') then
    select * into e from private.titan_club_events where id = p_event and club_id = p_club for update;
    if e.id is null then raise exception 'SLOT_NOT_FOUND' using errcode = 'P0002'; end if;
    if p_action = 'cancel_series' then
      if e.status = 'cancelled' then raise exception 'SERIES_CANCELLED' using errcode = '22023'; end if;
      update private.titan_club_events set status = 'cancelled', cancelled_at = now() where id = e.id;
      update private.titan_club_event_slots set status = 'cancelled', by_series = true, changed_at = clock_timestamp()
       where event_id = e.id and status = 'scheduled' and starts_at > now();
      perform private.titan_club_agenda_change(e.id, null, 'series_cancelled', null, null, v_uid);
    elsif p_action = 'resume_series' then
      if e.status = 'active' then raise exception 'SERIES_ACTIVE' using errcode = '22023'; end if;
      if not exists (select 1 from private.titan_club_event_slots where event_id = e.id and by_series and starts_at > now() + interval '30 minutes') then
        raise exception 'SLOT_STARTED' using errcode = '22023';
      end if;
      update private.titan_club_events set status = 'active', cancelled_at = null where id = e.id;
      -- The same rows come back: nothing is duplicated, the answers given before are kept and marked « to confirm ».
      update private.titan_club_event_slots set status = 'scheduled', by_series = false, changed_at = clock_timestamp()
       where event_id = e.id and by_series and starts_at > now() + interval '30 minutes';
      perform private.titan_club_agenda_change(e.id, null, 'series_resumed', null, null, v_uid);
    else
      if e.status <> 'active' then raise exception 'SERIES_CANCELLED' using errcode = '22023'; end if;
      update private.titan_club_events set code = private.titan_club_agenda_code() where id = e.id;
      perform private.titan_club_agenda_change(e.id, null, 'code_renewed', null, null, v_uid);
    end if;
    return public.titan_club_agenda_v1(p_club);
  end if;

  -- Actions on one occurrence.
  select s0.* into s from private.titan_club_event_slots s0 join private.titan_club_events e0 on e0.id = s0.event_id
   where s0.id = p_slot and e0.club_id = p_club for update of s0;
  if s.id is null then raise exception 'SLOT_NOT_FOUND' using errcode = 'P0002'; end if;
  select * into e from private.titan_club_events where id = s.event_id;
  select * into a from private.titan_club_event_answers where slot_id = s.id and user_id = v_uid;
  v_end := s.starts_at + make_interval(mins => e.duration_min);

  if p_action = 'answer' then
    if p_answer is null or p_answer not in ('yes', 'maybe', 'no') then raise exception 'AGENDA_INVALID' using errcode = '22023'; end if;
    if s.status = 'cancelled' then raise exception 'SLOT_CANCELLED' using errcode = '22023'; end if;
    if now() >= s.starts_at then raise exception 'SLOT_STARTED' using errcode = '22023'; end if;
    perform private.titan_rate_limit(v_uid, 'club_agenda_answer', 60);
    v_answer := p_answer;
    if p_answer = 'yes' and a.answer in ('yes', 'waitlist') then
      v_answer := a.answer;   -- already counted, or already waiting in order: an answer repeated changes nothing
    elsif p_answer = 'yes' and e.capacity is not null then
      select count(*) into v_yes from private.titan_club_event_answers where slot_id = s.id and answer = 'yes' and user_id <> v_uid;
      if v_yes >= e.capacity then v_answer := 'waitlist'; end if;
    end if;
    insert into private.titan_club_event_answers (slot_id, user_id, answer, answered_at, confirmed_at)
    values (s.id, v_uid, v_answer, clock_timestamp(), clock_timestamp())
    on conflict (slot_id, user_id) do update set answer = excluded.answer, confirmed_at = excluded.confirmed_at,
      -- Repeating one's answer confirms it and keeps one's place in the waiting list.
      answered_at = case when excluded.answer = private.titan_club_event_answers.answer then private.titan_club_event_answers.answered_at else excluded.answered_at end,
      promoted_at = case when excluded.answer = private.titan_club_event_answers.answer then private.titan_club_event_answers.promoted_at end,
      reminder = case when excluded.answer = 'no' then false else private.titan_club_event_answers.reminder end;
    if a.answer = 'yes' and v_answer <> 'yes' then perform private.titan_club_agenda_fill(s.id); end if;
  elsif p_action = 'remind' then
    if a.user_id is null or a.answer not in ('yes', 'maybe', 'waitlist') then raise exception 'ANSWER_REQUIRED' using errcode = '22023'; end if;
    if s.status = 'cancelled' then raise exception 'SLOT_CANCELLED' using errcode = '22023'; end if;
    if now() >= s.starts_at then raise exception 'SLOT_STARTED' using errcode = '22023'; end if;
    update private.titan_club_event_answers set reminder = coalesce(p_on, false) where slot_id = s.id and user_id = v_uid;
  elsif p_action = 'attend' then
    if s.status = 'cancelled' then raise exception 'SLOT_CANCELLED' using errcode = '22023'; end if;
    if now() < s.starts_at then raise exception 'SLOT_NOT_STARTED' using errcode = '22023'; end if;
    if now() >= v_end + interval '7 days' then raise exception 'SLOT_CLOSED' using errcode = '22023'; end if;
    if p_on is null then raise exception 'AGENDA_INVALID' using errcode = '22023'; end if;
    -- Declaring a presence never writes a session: it is a statement, nothing more. Saying « I was not there » unlinks.
    insert into private.titan_club_event_answers (slot_id, user_id, answer, answered_at, confirmed_at, attended, attended_at)
    values (s.id, v_uid, null, clock_timestamp(), clock_timestamp(), p_on, clock_timestamp())
    on conflict (slot_id, user_id) do update set attended = excluded.attended, attended_at = excluded.attended_at,
      log_id = case when excluded.attended then private.titan_club_event_answers.log_id end,
      linked_at = case when excluded.attended then private.titan_club_event_answers.linked_at end;
  elsif p_action = 'link' then
    if now() >= v_end + interval '7 days' then raise exception 'SLOT_CLOSED' using errcode = '22023'; end if;
    if a.attended is not true then raise exception 'PRESENCE_REQUIRED' using errcode = '22023'; end if;
    if p_log is null or not private.titan_club_agenda_log_ok(s.id, v_uid, p_log)
       or exists (select 1 from private.titan_club_event_answers y where y.log_id = p_log and not (y.slot_id = s.id and y.user_id = v_uid)) then
      raise exception 'LOG_NOT_ELIGIBLE' using errcode = '22023';
    end if;
    update private.titan_club_event_answers set log_id = p_log, linked_at = clock_timestamp() where slot_id = s.id and user_id = v_uid;
  elsif p_action = 'unlink' then
    update private.titan_club_event_answers set log_id = null, linked_at = null where slot_id = s.id and user_id = v_uid;
  elsif p_action = 'move' then
    if s.status = 'cancelled' then raise exception 'SLOT_CANCELLED' using errcode = '22023'; end if;
    if now() >= s.starts_at then raise exception 'SLOT_STARTED' using errcode = '22023'; end if;
    if p_starts_at is null or p_starts_at < now() + interval '30 minutes' or p_starts_at > now() + interval '60 days' or p_starts_at = s.starts_at then
      raise exception 'AGENDA_INVALID' using errcode = '22023';
    end if;
    update private.titan_club_event_slots set starts_at = p_starts_at, changed_at = clock_timestamp() where id = s.id;
    perform private.titan_club_agenda_change(e.id, s.id, 'moved', s.starts_at, p_starts_at, v_uid);
  elsif p_action = 'fallback' then
    if e.fallback is null then raise exception 'NO_FALLBACK' using errcode = '22023'; end if;
    if s.status = 'cancelled' then raise exception 'SLOT_CANCELLED' using errcode = '22023'; end if;
    if now() >= s.starts_at then raise exception 'SLOT_STARTED' using errcode = '22023'; end if;
    if coalesce(p_on, true) <> s.fallback_on then
      update private.titan_club_event_slots set fallback_on = coalesce(p_on, true), changed_at = clock_timestamp() where id = s.id;
      perform private.titan_club_agenda_change(e.id, s.id, case when coalesce(p_on, true) then 'fallback_on' else 'fallback_off' end, s.starts_at, s.starts_at, v_uid);
    end if;
  elsif p_action = 'cancel' then
    if s.status = 'cancelled' then raise exception 'SLOT_CANCELLED' using errcode = '22023'; end if;
    if now() >= s.starts_at then raise exception 'SLOT_STARTED' using errcode = '22023'; end if;
    update private.titan_club_event_slots set status = 'cancelled', by_series = false, changed_at = clock_timestamp() where id = s.id;
    perform private.titan_club_agenda_change(e.id, s.id, 'cancelled', s.starts_at, null, v_uid);
  elsif p_action = 'restore' then
    if s.status <> 'cancelled' then raise exception 'AGENDA_INVALID' using errcode = '22023'; end if;
    if e.status <> 'active' then raise exception 'SERIES_CANCELLED' using errcode = '22023'; end if;
    if now() >= s.starts_at then raise exception 'SLOT_STARTED' using errcode = '22023'; end if;
    update private.titan_club_event_slots set status = 'scheduled', by_series = false, changed_at = clock_timestamp() where id = s.id;
    perform private.titan_club_agenda_change(e.id, s.id, 'restored', null, s.starts_at, v_uid);
  end if;
  return public.titan_club_agenda_v1(p_club);
end;
$function$;

-- The invitation link. A CURRENT member of the club reads the meeting while its series has an occurrence to come; anyone else learns
-- nothing (« unavailable »: unknown, renewed, other club, former member), and a member of a finished or cancelled series reads
-- « expired »: no title, no time, no place in either case. Never an error for a wrong code, so that the rate limit holds.
create or replace function public.titan_club_agenda_invite_v1(p_code text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $function$
declare v_uid uuid := auth.uid(); v_code text := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
  e private.titan_club_events%rowtype; v_role text; v_slot uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  if not private.titan_flag_on('screens.club_agenda') then raise exception 'FEATURE_DISABLED' using errcode = '42501'; end if;
  perform private.titan_rate_limit(v_uid, 'club_agenda_invite', 30);
  if v_code !~ '^[A-Z2-9]{8}$' then return jsonb_build_object('status', 'unavailable'); end if;
  select * into e from private.titan_club_events where code = v_code;
  if e.id is null then return jsonb_build_object('status', 'unavailable'); end if;
  select m.role into v_role from private.titan_club_members m join private.titan_clubs c on c.id = m.club_id
   where m.club_id = e.club_id and m.user_id = v_uid and c.archived_at is null;
  if v_role is null then return jsonb_build_object('status', 'unavailable'); end if;
  select s.id into v_slot from private.titan_club_event_slots s
   where s.event_id = e.id and s.status = 'scheduled' and s.starts_at + make_interval(mins => e.duration_min) > now()
   order by s.starts_at limit 1;
  if e.status <> 'active' or v_slot is null then return jsonb_build_object('status', 'expired'); end if;
  return jsonb_build_object('status', 'open', 'club', e.club_id, 'slot', private.titan_club_agenda_slot(v_slot, v_uid, v_role));
end;
$function$;
revoke all on function public.titan_club_agenda_v1(uuid), public.titan_club_agenda_act_v1(uuid, text, uuid, uuid, text, boolean, timestamptz, uuid, jsonb),
  public.titan_club_agenda_invite_v1(text) from public, anon;
grant execute on function public.titan_club_agenda_v1(uuid), public.titan_club_agenda_act_v1(uuid, text, uuid, uuid, text, boolean, timestamptz, uuid, jsonb),
  public.titan_club_agenda_invite_v1(text) to authenticated;

-- A « yes » withdrawn (a departure from the club, an erased account) frees its place for the first one waiting, while the occurrence is to come.
create or replace function private.titan_club_agenda_answer_freed()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
begin
  if exists (select 1 from private.titan_club_event_slots s where s.id = old.slot_id and s.status = 'scheduled' and s.starts_at > now()) then
    perform private.titan_club_agenda_fill(old.slot_id);
  end if;
  return old;
end;
$function$;
revoke all on function private.titan_club_agenda_answer_freed() from public, anon, authenticated;
drop trigger if exists titan_club_event_answers_freed on private.titan_club_event_answers;
create trigger titan_club_event_answers_freed after delete on private.titan_club_event_answers
  for each row when (old.answer = 'yes') execute function private.titan_club_agenda_answer_freed();

-- Leaving the club, or being removed from it: the answers to occurrences still to come are withdrawn (a place held goes to the first one
-- waiting); answers and presences of meetings already started stay with the group's counts.
create or replace function private.titan_club_agenda_member_left()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
begin
  delete from private.titan_club_event_answers a
   using private.titan_club_event_slots s, private.titan_club_events e
   where s.id = a.slot_id and e.id = s.event_id and e.club_id = old.club_id and a.user_id = old.user_id and s.starts_at > now();
  return old;
end;
$function$;
revoke all on function private.titan_club_agenda_member_left() from public, anon, authenticated;
drop trigger if exists titan_club_members_agenda on private.titan_club_members;
create trigger titan_club_members_agenda after delete on private.titan_club_members
  for each row execute function private.titan_club_agenda_member_left();

-- ---------------------------------------------------------------------------------------------
-- 5. « Depuis ta dernière visite »: the meetings that ask for an answer. Nothing is pushed.
-- ---------------------------------------------------------------------------------------------
-- Reasons, one per occurrence, in this order of priority: promoted (a place was freed for me), cancelled (a meeting I was coming to),
-- toConfirm (its time or plan changed after my answer), reminder (I asked to be reminded, it starts within 24 hours), answer (the next
-- occurrence of a series, within 14 days, that I have not answered), presence (it ended in the last 7 days and I have not said if I was there).
create or replace function private.titan_club_agenda_digest(p_uid uuid, p_since timestamptz)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with cand as (
    select s.id, e.club_id, c.name as club_name, e.title, s.starts_at,
           case
             when a.answer = 'yes' and a.promoted_at > p_since and s.status = 'scheduled' and s.starts_at > now() then 'promoted'
             when a.answer in ('yes', 'maybe', 'waitlist') and s.status = 'cancelled' and s.changed_at > greatest(p_since, a.confirmed_at)
                  and s.planned_at > now() - interval '1 day' then 'cancelled'
             when a.answer in ('yes', 'maybe', 'waitlist') and s.status = 'scheduled' and s.starts_at > now() and s.changed_at > a.confirmed_at then 'toConfirm'
             when a.answer = 'yes' and a.reminder and s.status = 'scheduled' and s.starts_at > now() and s.starts_at <= now() + interval '24 hours' then 'reminder'
             when a.user_id is null and e.status = 'active' and s.status = 'scheduled' and s.starts_at > now() and s.starts_at <= now() + interval '14 days'
                  and s.id = (select s2.id from private.titan_club_event_slots s2 where s2.event_id = e.id and s2.status = 'scheduled'
                               and s2.starts_at > now() order by s2.starts_at, s2.n limit 1) then 'answer'
             when a.answer in ('yes', 'maybe', 'waitlist') and a.attended is null and s.status = 'scheduled'
                  and s.starts_at + make_interval(mins => e.duration_min) <= now()
                  and s.starts_at + make_interval(mins => e.duration_min) > now() - interval '7 days' then 'presence'
           end as reason
      from private.titan_club_members m
      join private.titan_clubs c on c.id = m.club_id and c.archived_at is null
      join private.titan_club_events e on e.club_id = m.club_id
      join private.titan_club_event_slots s on s.event_id = e.id
      left join private.titan_club_event_answers a on a.slot_id = s.id and a.user_id = p_uid
     where m.user_id = p_uid and s.starts_at > now() - interval '8 days' and s.starts_at < now() + interval '15 days'),
  ranked as (
    select cand.*, array_position(array['promoted', 'cancelled', 'toConfirm', 'reminder', 'answer', 'presence'], cand.reason) as prio
      from cand where cand.reason is not null
     order by 7, cand.starts_at, cand.id limit 6)
  select case when not private.titan_flag_on('screens.club_agenda') then '[]'::jsonb else
    coalesce((select jsonb_agg(jsonb_build_object('slot', r.id, 'club', r.club_id, 'clubName', r.club_name, 'title', r.title, 'startsAt', r.starts_at,
                'reason', r.reason) order by r.prio, r.starts_at, r.id) from ranked r), '[]'::jsonb) end;
$$;
revoke all on function private.titan_club_agenda_digest(uuid, timestamptz) from public, anon, authenticated;

-- The digest of 20261126090000 (V1.8.3), with the club meetings.
create or replace function public.titan_social_digest_v1(p_since timestamptz default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
set statement_timeout = '8s'
as $function$
declare
  v_uid uuid := auth.uid();
  v_since timestamptz;
  v_cordees jsonb;
  v_duo jsonb;
  v_friends integer;
  v_active28 integer;
  v_running integer;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  v_since := least(now() - interval '1 hour', greatest(now() - interval '30 days', coalesce(p_since, now() - interval '7 days')));
  -- Cordées first (this settles a summit that is due), then the Duo (this closes a lapsed pairing and keeps its result).
  v_cordees := coalesce(public.titan_cordees_v1() -> 'cordees', '[]'::jsonb);
  v_duo := case when to_regprocedure('public.titan_buddy_v1()') is not null then public.titan_buddy_v1() else null end;
  select count(*)::integer into v_friends
    from public.friendships f
   where (f.user_id_1 = v_uid or f.user_id_2 = v_uid) and f.status = 'accepted'
     and private.titan_are_friends(f.user_id_1, f.user_id_2);
  select count(*)::integer into v_active28 from private.titan_effort_days(v_uid, now() - interval '28 days', now() + interval '1 minute', '-infinity'::timestamptz, 90) d where d.minutes > 0;
  select count(*)::integer into v_running from jsonb_array_elements(v_cordees) c where c->>'status' = 'active' and c->>'myStatus' = 'joined';
  return jsonb_build_object(
    'since', v_since,
    'requestsIn', (select count(*) from public.friendships f where f.user_id_2 = v_uid and f.status = 'pending'
                     and f.created_at > now() - interval '30 days' and f.created_at > v_since),
    'cheersReceived', (select count(*) from public.titan_moment_cheers c join public.titan_moments m on m.id = c.moment_id
                         where m.user_id = v_uid and c.created_at > v_since and private.titan_are_friends(v_uid, c.user_id)),
    'friendMoments', jsonb_build_object(
      'count', (select count(*) from public.titan_moments m
                 where m.user_id <> v_uid and m.visibility = 'friends' and not m.hidden and m.created_at > v_since and private.titan_are_friends(v_uid, m.user_id)),
      'latest', coalesce((select jsonb_agg(x.j order by x.at desc) from (
          select m.created_at as at, jsonb_build_object('id', m.id, 'kind', m.kind, 'title', m.title, 'at', m.created_at,
                   'author', coalesce(nullif(p.username, ''), 'Athlète')) as j
            from public.titan_moments m join public.profiles p on p.id = m.user_id
           where m.user_id <> v_uid and m.visibility = 'friends' and not m.hidden and m.created_at > v_since and private.titan_are_friends(v_uid, m.user_id)
           order by m.created_at desc limit 3) x), '[]'::jsonb)),
    -- Only friends who allow it (privacy.socialPresence) and only that they were active, never what, where or how much.
    'friendsActive', coalesce((select jsonb_agg(x.name order by x.name) from (
        select distinct coalesce(nullif(p.username, ''), 'Athlète') as name
          from public.friendships f
          join public.profiles p on p.id = case when f.user_id_1 = v_uid then f.user_id_2 else f.user_id_1 end
         where (f.user_id_1 = v_uid or f.user_id_2 = v_uid) and f.status = 'accepted' and private.titan_are_friends(v_uid, p.id)
           and not coalesce(p.is_suspended, false) and coalesce((p.privacy ->> 'socialPresence')::boolean, false)
           and exists (select 1 from private.titan_confirmed_sessions(p.id, v_since, now() + interval '1 minute', '-infinity'::timestamptz))
         limit 8) x), '[]'::jsonb),
    'cordees', coalesce((select jsonb_agg(jsonb_build_object('id', c->>'id', 'route', c->>'route', 'status', c->>'status', 'myStatus', c->>'myStatus',
                 'percent', (c->>'percent')::integer, 'camps', (c->>'camps')::integer, 'total', (c->>'total')::integer, 'target', (c->>'target')::integer,
                 'mine', (c->'me'->>'counted')::integer, 'earned', (c->>'earned')::boolean,
                 'summitedSince', c->>'status' = 'summited' and (c->>'summitedAt')::timestamptz > v_since, 'endsAt', c->>'endsAt',
                 -- V1.8.3: the finished cordée a new one follows (its route only).
                 'follows', case when jsonb_typeof(c->'follows') = 'object' then c->'follows'->>'route' end))
               from jsonb_array_elements(v_cordees) c where c->>'myStatus' in ('joined', 'invited')), '[]'::jsonb),
    -- V1.8.3: finished cordées whose group is setting off again, only when one proposal waits for my answer or I proposed one.
    'suites', coalesce((select jsonb_agg(jsonb_build_object('id', c->>'id', 'route', c->>'route',
                 'waiting', (c->'suite'->>'waiting')::integer, 'choice', (c->'suite'->>'choice')::boolean,
                 'proposals', (select coalesce(jsonb_agg(jsonb_build_object('id', p->>'id', 'route', p->>'route', 'pace', p->>'pace', 'days', (p->>'days')::integer,
                                  'status', p->>'status', 'mine', (p->>'mine')::boolean, 'by', p->'by'->>'name', 'myAnswer', p->>'myAnswer',
                                  'yes', (p->>'yes')::integer, 'eligible', (p->>'eligible')::integer, 'turn', p->'turn')), '[]'::jsonb)
                                 from jsonb_array_elements(c->'suite'->'proposals') p where p->>'status' in ('open', 'started') and jsonb_array_length(p->'turn') > 0)))
               from jsonb_array_elements(v_cordees) c
              where jsonb_typeof(c->'suite') = 'object'
                and exists (select 1 from jsonb_array_elements(c->'suite'->'proposals') p where p->>'status' in ('open', 'started') and jsonb_array_length(p->'turn') > 0)), '[]'::jsonb),
    'duo', case
      when v_duo is null then null
      when v_duo->>'status' = 'active' then jsonb_build_object('status', 'active', 'partner', v_duo->'partner'->>'name', 'together', (v_duo->>'together')::integer,
             'target', (v_duo->>'target')::integer, 'daysLeft', (v_duo->>'daysLeft')::integer)
      when v_duo->>'status' = 'pending' and v_duo->>'role' = 'invitee' then jsonb_build_object('status', 'invited', 'partner', v_duo->'partner'->>'name')
      when v_duo->'last' is not null and v_duo->'last' <> 'null'::jsonb and ((v_duo->'last'->>'endsOn')::date + 1)::timestamp at time zone 'Europe/Paris' > v_since
        then jsonb_build_object('status', 'finished', 'partner', v_duo->'last'->'partner'->>'name', 'together', (v_duo->'last'->>'together')::integer,
             'target', (v_duo->'last'->>'target')::integer, 'reached', (v_duo->'last'->>'reached')::boolean)
      else null end,
    'challengesEnded', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'title', c.title, 'reached', r.reached) order by c.ends_at desc)
        from public.titan_challenges c
        join public.titan_challenge_members m on m.challenge_id = c.id and m.user_id = v_uid and m.status = 'joined'
        left join private.titan_challenge_results r on r.challenge_id = c.id and r.user_id = v_uid
       where c.kind = 'individual' and c.ends_at > v_since and c.ends_at <= now()), '[]'::jsonb),
    -- Shared memories: the last summits one took part in, more than a week ago.
    'memories', coalesce((select jsonb_agg(x.j order by x.at desc) from (
        select c.summited_at as at, jsonb_build_object('id', c.id, 'route', c.route, 'summitedAt', c.summited_at,
                 'members', (select count(*) from private.titan_challenge_results y where y.challenge_id = c.id)) as j
          from public.titan_challenges c join private.titan_challenge_results r on r.challenge_id = c.id and r.user_id = v_uid and r.reached
         where c.kind = 'cordee' and c.summited_at is not null and c.summited_at < now() - interval '7 days'
         order by c.summited_at desc limit 3) x), '[]'::jsonb),
    -- V1.8.6: the club meetings that ask for an answer (closed flag: none).
    'agenda', private.titan_club_agenda_digest(v_uid, v_since),
    -- One suggestion, only when it can help: a pace that fits the last 28 days (never more than what was done), solo or with friends.
    'suggestion', case when v_running = 0 then jsonb_build_object('kind', 'cordee', 'activeDays28', v_active28,
        'pace', case when v_active28 >= 16 then 'soutenue' when v_active28 >= 8 then 'reguliere' else 'douce' end, 'friends', v_friends)
      else null end
  );
end;
$function$;
revoke all on function public.titan_social_digest_v1(timestamptz) from public, anon;
grant execute on function public.titan_social_digest_v1(timestamptz) to authenticated;

-- ---------------------------------------------------------------------------------------------
-- 6. The account export (cumulative): the meetings one organised, one's own answers, presences and linked sessions; never another member.
-- ---------------------------------------------------------------------------------------------
create or replace function private.titan_social_export_v1(p_uid uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'friendInvites', coalesce((select jsonb_agg(jsonb_build_object('created_at', i.created_at, 'expires_at', i.expires_at, 'revoked_at', i.revoked_at,
                       'used_at', i.used_at) order by i.created_at) from private.titan_friend_invites i where i.created_by = p_uid), '[]'::jsonb),
    'cordeeTitles', coalesce((select jsonb_agg(jsonb_build_object('route', t.route, 'challenge_id', t.challenge_id, 'earned_at', t.earned_at)
                       order by t.earned_at, t.route) from private.titan_cordee_titles t where t.user_id = p_uid), '[]'::jsonb),
    'cordeeRelays', coalesce((select jsonb_agg(x.j order by x.at) from (
        select r.opened_at as at, jsonb_build_object('challenge_id', r.challenge_id, 'step', r.step, 'action', 'transmit', 'at', r.opened_at,
               'log_id', r.opened_log, 'day', r.opened_day) as j from private.titan_cordee_relays r where r.opened_by = p_uid
        union all
        select r.confirmed_at, jsonb_build_object('challenge_id', r.challenge_id, 'step', r.step, 'action', 'confirm', 'at', r.confirmed_at,
               'log_id', r.confirmed_log, 'day', r.confirmed_day) from private.titan_cordee_relays r where r.confirmed_by = p_uid) x), '[]'::jsonb),
    'cordeeRelayTurns', coalesce((select jsonb_agg(jsonb_build_object('challenge_id', t.challenge_id, 'kind', t.kind,
        'role', case when t.kind = 'take' then 'took' when t.from_user = p_uid then 'offered' when t.accepted_by = p_uid then 'accepted' else 'offered_to_me' end,
        'open', case when t.kind = 'handover' then t.to_user is null end, 'status', t.status, 'at', t.created_at, 'expires_at', t.expires_at,
        'resolved_at', t.resolved_at) order by t.created_at)
      from private.titan_cordee_relay_turns t where t.from_user = p_uid or t.to_user = p_uid or t.accepted_by = p_uid), '[]'::jsonb),
    'cordeeSuites', coalesce((select jsonb_agg(x.j order by x.at) from (
        select s.created_at as at, jsonb_build_object('from_id', s.from_id, 'role', 'proposed', 'route', s.route, 'pace', s.pace, 'days', s.days,
               'status', s.status, 'at', s.created_at, 'started_id', s.started_id) as j
          from private.titan_cordee_suites s where s.proposed_by = p_uid
        union all
        select a.answered_at, jsonb_build_object('from_id', s.from_id, 'role', 'answered', 'answer', a.answer, 'route', s.route, 'pace', s.pace,
               'days', s.days, 'at', a.answered_at)
          from private.titan_cordee_suite_answers a join private.titan_cordee_suites s on s.id = a.suite_id
         where a.user_id = p_uid and s.proposed_by is distinct from p_uid) x), '[]'::jsonb),
    'clubSeasons', coalesce((select jsonb_agg(x.j order by x.at) from (
        select s.created_at as at, jsonb_build_object('season_id', s.id, 'club_id', s.club_id, 'role', 'organised', 'title', s.title, 'pace', s.pace,
               'weeks', s.weeks, 'starts_at', s.starts_at, 'status', s.status, 'at', s.created_at) as j
          from private.titan_club_seasons s where s.created_by = p_uid
        union all
        select m.joined_at, jsonb_build_object('season_id', m.season_id, 'club_id', s.club_id, 'role', 'took_part', 'title', s.title, 'joined_at', m.joined_at,
               'left_at', m.left_at, 'final_days', m.final_days,
               'pauses', coalesce((select jsonb_agg(jsonb_build_object('paused_at', p.paused_at, 'resumed_at', p.resumed_at) order by p.paused_at)
                                     from private.titan_club_season_pauses p where p.season_id = m.season_id and p.user_id = p_uid), '[]'::jsonb))
          from private.titan_club_season_members m join private.titan_club_seasons s on s.id = m.season_id where m.user_id = p_uid) x), '[]'::jsonb),
    'clubMatches', coalesce((select jsonb_agg(x.j order by x.at) from (
        select y.created_at as at, jsonb_build_object('match_id', y.id, 'club_id', y.host_club, 'role', 'proposed', 'format', y.format, 'pace', y.pace,
               'weeks', y.weeks, 'starts_at', y.starts_at, 'status', y.status, 'at', y.created_at) as j
          from private.titan_club_matches y where y.created_by = p_uid
        union all
        select y.answered_at, jsonb_build_object('match_id', y.id, 'club_id', y.guest_club, 'role', case when y.status = 'refused' then 'refused' else 'accepted' end,
               'format', y.format, 'starts_at', y.starts_at, 'at', y.answered_at)
          from private.titan_club_matches y where y.answered_by = p_uid
        union all
        select m.joined_at, jsonb_build_object('match_id', m.match_id, 'club_id', m.club_id, 'role', 'took_part', 'format', y.format, 'joined_at', m.joined_at,
               'left_at', m.left_at, 'final_days', m.final_days, 'final_share', m.final_share, 'clear', m.clear, 'again', m.again, 'answered_at', m.answered_at)
          from private.titan_club_match_members m join private.titan_club_matches y on y.id = m.match_id where m.user_id = p_uid) x), '[]'::jsonb),
    'clubAgenda', coalesce((select jsonb_agg(x.j order by x.at) from (
        select e.created_at as at, jsonb_build_object('event_id', e.id, 'club_id', e.club_id, 'role', 'organised', 'title', e.title, 'area', e.area,
               'place', e.place, 'fallback', e.fallback, 'recurrence', e.recurrence, 'occurrences', e.occurrences, 'capacity', e.capacity,
               'status', e.status, 'at', e.created_at) as j
          from private.titan_club_events e where e.created_by = p_uid
        union all
        select a.answered_at, jsonb_build_object('event_id', e.id, 'club_id', e.club_id, 'role', 'answered', 'title', e.title, 'slot', s.n,
               'starts_at', s.starts_at, 'answer', a.answer, 'answered_at', a.answered_at, 'promoted_at', a.promoted_at, 'reminder', a.reminder,
               'attended', a.attended, 'attended_at', a.attended_at, 'log_id', a.log_id, 'linked_at', a.linked_at)
          from private.titan_club_event_answers a join private.titan_club_event_slots s on s.id = a.slot_id
          join private.titan_club_events e on e.id = s.event_id where a.user_id = p_uid) x), '[]'::jsonb));
$$;
revoke all on function private.titan_social_export_v1(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- 7. The measure of the pilot: meetings held, confirmed answers, return the following week. Counts only.
-- ---------------------------------------------------------------------------------------------
-- held: an occurrence that ended, was not cancelled and has at least one declared presence. returned: among the presences declared at
-- meetings that ended at least 7 days ago, those followed within 7 days by a confirmed session or by a « yes » to another meeting of the club.
create or replace function private.titan_club_agenda_measure(p_since timestamptz default now() - interval '56 days')
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with sl as (
    select s.*, e.club_id, e.capacity, s.starts_at + make_interval(mins => e.duration_min) as ends_at
      from private.titan_club_event_slots s join private.titan_club_events e on e.id = s.event_id
     where s.starts_at >= p_since and s.starts_at <= now() + interval '60 days'),
  ended as (select * from sl where sl.status = 'scheduled' and sl.ends_at <= now()),
  pres as (
    select a.user_id, x.id, x.club_id, x.ends_at from ended x join private.titan_club_event_answers a on a.slot_id = x.id
     where a.attended is true and x.ends_at <= now() - interval '7 days')
  select jsonb_build_object('since', p_since,
    'series', (select count(*) from private.titan_club_events e where e.created_at >= p_since),
    'weekly', (select count(*) from private.titan_club_events e where e.created_at >= p_since and e.recurrence = 'weekly'),
    'occurrencesEnded', (select count(*) from ended),
    'held', (select count(*) from ended x where exists (select 1 from private.titan_club_event_answers a where a.slot_id = x.id and a.attended is true)),
    'cancelled', (select count(*) from sl where sl.status = 'cancelled'),
    'moved', (select count(*) from private.titan_club_event_changes c join sl on sl.id = c.slot_id where c.kind = 'moved'),
    'confirmedAnswers', (select count(*) from ended x join private.titan_club_event_answers a on a.slot_id = x.id where a.answer = 'yes'),
    'waitlistPromoted', (select count(*) from sl join private.titan_club_event_answers a on a.slot_id = sl.id where a.promoted_at is not null),
    'presences', (select count(*) from ended x join private.titan_club_event_answers a on a.slot_id = x.id where a.attended is true),
    'linked', (select count(*) from ended x join private.titan_club_event_answers a on a.slot_id = x.id where a.log_id is not null),
    'returnEligible', (select count(*) from pres),
    'returned', (select count(*) from pres p where
        exists (select 1 from private.titan_confirmed_sessions(p.user_id, p.ends_at + interval '1 hour', p.ends_at + interval '7 days', '-infinity'::timestamptz))
        or exists (select 1 from private.titan_club_event_answers a2 join private.titan_club_event_slots s2 on s2.id = a2.slot_id
                    join private.titan_club_events e2 on e2.id = s2.event_id
                   where a2.user_id = p.user_id and e2.club_id = p.club_id and a2.answer = 'yes' and s2.id <> p.id
                     and s2.starts_at > p.ends_at and s2.starts_at <= p.ends_at + interval '7 days')));
$$;
revoke all on function private.titan_club_agenda_measure(timestamptz) from public, anon, authenticated;
grant execute on function private.titan_club_agenda_measure(timestamptz) to service_role;

notify pgrst, 'reload schema';
-- <<< repository file
insert into supabase_migrations.schema_migrations (version, name) values ('20261130104600', 'club_agenda');
commit;
